export const NETWORKS_SPECIFIC_CATALOG_WORKFLOW_COUNT = Object.keys(NETWORKS_SPECIFIC_WORKFLOWS).length;
export const hasNetworksSpecificCatalogWorkflow = (name: string): boolean => Boolean(NETWORKS_SPECIFIC_WORKFLOWS[name]);
export const networksSpecificCatalogWorkflow = (name: string): TechniqueStepDefinition[] | undefined => NETWORKS_SPECIFIC_WORKFLOWS[name]?.map((item) => ({ ...item }));